import os, json, numpy as np

N = 26

# ---------- Load our own packing (unchanged return) ----------
def read_txt_matrix(path, shape):
    try:
        arr = np.loadtxt(path)
        arr = np.array(arr, dtype=float).reshape(shape)
        return arr
    except Exception:
        return None

def load_noesis_pack():
    c = read_txt_matrix('storage/noesis/latest_centers.txt', (N, 2))
    r = read_txt_matrix('storage/noesis/latest_radii.txt', (N,))
    if c is not None and r is not None:
        return c, r
    # Fallback: grid + hole seed with tiny margins
    r0 = 0.1 - 1e-8
    coords = [0.1, 0.3, 0.5, 0.7, 0.9]
    centers = [[x, y] for x in coords for y in coords]  # 25
    hole = np.array([0.2, 0.2])
    d = float(np.linalg.norm(hole - np.array([0.1, 0.1])))
    r_hole = d - r0 - 1e-8
    radii = [r0]*25 + [r_hole]
    return np.array(centers, float), np.array(radii, float)

# ---------- Parsing and canonicalization ----------
def canonicalize_label(lbl):
    m = {'xmin':'xL','xmax':'xR','ymin':'yB','ymax':'yT',
         'xl':'xL','xr':'xR','yb':'yB','yt':'yT',
         'xL':'xL','xR':'xR','yB':'yB','yT':'yT'}
    s = str(lbl).strip()
    return m.get(s, s)

def read_summary_index_base(folder):
    for name in ['summary_tol1e8.json', 'summary_tol1e08.json']:
        p = os.path.join(folder, name)
        if os.path.isfile(p):
            try:
                with open(p, 'r') as f:
                    js = json.load(f)
                ib = js.get('index_base', None)
                return 0 if ib == 0 else (1 if ib == 1 else None)
            except Exception:
                pass
    return None

def read_boundary_csv(folder):
    for fname in ['active_boundary_tol1e8.csv', 'active_boundary_tol1e08.csv']:
        path = os.path.join(folder, fname)
        if os.path.isfile(path):
            break
    else:
        return set()
    base = read_summary_index_base(folder)
    S = set()
    try:
        with open(path, 'r') as f:
            for ln, line in enumerate(f):
                parts = [p.strip() for p in line.strip().split(',')]
                if ln == 0:
                    # header check
                    if len(parts) >= 2 and not parts[0].isdigit():
                        continue
                if len(parts) < 2:
                    continue
                i_raw, lbl_raw = parts[0], parts[1]
                if not i_raw:
                    continue
                i = int(i_raw)
                if base is None:
                    if i >= N:  # auto-adjust
                        i -= 1
                elif base == 1:
                    i -= 1
                lbl = canonicalize_label(lbl_raw)
                if 0 <= i < N:
                    S.add((i, lbl))
    except Exception:
        return set()
    return S

def read_pairs_csv(folder):
    for fname in ['active_pairs_tol1e8.csv', 'active_pairs_tol1e08.csv']:
        path = os.path.join(folder, fname)
        if os.path.isfile(path):
            break
    else:
        return set()
    base = read_summary_index_base(folder)
    P = set()
    try:
        with open(path, 'r') as f:
            for ln, line in enumerate(f):
                parts = [p.strip() for p in line.strip().split(',')]
                if ln == 0:
                    if len(parts) >= 2 and not parts[0].isdigit():
                        continue
                if len(parts) < 2:
                    continue
                a_raw, b_raw = parts[0], parts[1]
                if not a_raw or not b_raw:
                    continue
                a = int(a_raw); b = int(b_raw)
                if base is None:
                    if max(a, b) >= N:
                        a -= 1; b -= 1
                elif base == 1:
                    a -= 1; b -= 1
                if a == b:
                    continue
                i, j = (a, b) if a < b else (b, a)
                if 0 <= i < N and 0 <= j < N:
                    P.add((i, j))
    except Exception:
        return set()
    return P

def jaccard(A, B):
    inter = len(A & B)
    union = len(A | B)
    J = (inter / union) if union > 0 else 0.0
    return inter, union, J

def write_jaccard(out_base, bj, pj, sizes, meta=None):
    os.makedirs(os.path.dirname(out_base), exist_ok=True)
    data = {
        'tolerance': '1e-8',
        'boundary': {
            'intersection': bj[0], 'union': bj[1], 'jaccard': round(bj[2], 6),
            'sizes': {'A': sizes['boundary'][0], 'B': sizes['boundary'][1]}
        },
        'pairs': {
            'intersection': pj[0], 'union': pj[1], 'jaccard': round(pj[2], 6),
            'sizes': {'A': sizes['pairs'][0], 'B': sizes['pairs'][1]}
        }
    }
    if meta: data['meta'] = meta
    with open(out_base + '.json', 'w') as f:
        json.dump(data, f, indent=2, sort_keys=True)
    with open(out_base + '.csv', 'w') as f:
        f.write('type,intersection,union,jaccard,|A|,|B|\n')
        f.write(f'boundary,{bj[0]},{bj[1]},{bj[2]:.6f},{sizes["boundary"][0]},{sizes["boundary"][1]}\n')
        f.write(f'pairs,{pj[0]},{pj[1]},{pj[2]:.6f},{sizes["pairs"][0]},{sizes["pairs"][1]}\n')

def write_consensus(out_base, sets_dict):
    # sets_dict: {'N':(B,P), 'S':(...), 'P':(...), 'I':(...)}
    B_sets = [v[0] for v in sets_dict.values() if v[0]]
    P_sets = [v[1] for v in sets_dict.values() if v[1]]
    if not B_sets or not P_sets:
        return
    B_int = set.intersection(*B_sets)
    B_uni = set.union(*B_sets)
    P_int = set.intersection(*P_sets)
    P_uni = set.union(*P_sets)
    os.makedirs(os.path.dirname(out_base), exist_ok=True)
    js = {
        'tolerance': '1e-8',
        'boundary': {'intersection': len(B_int), 'union': len(B_uni)},
        'pairs':    {'intersection': len(P_int), 'union': len(P_uni)},
        'sizes': {
            k: {'boundary': len(sets_dict[k][0]), 'pairs': len(sets_dict[k][1])}
            for k in sets_dict
        }
    }
    with open(out_base + '.json', 'w') as f:
        json.dump(js, f, indent=2, sort_keys=True)
    with open(out_base + '.csv', 'w') as f:
        f.write('set,|boundary|,|pairs|\n')
        for k in sets_dict:
            f.write(f'{k},{len(sets_dict[k][0])},{len(sets_dict[k][1])}\n')
        f.write('intersection,' + f'{len(B_int)},{len(P_int)}\n')
        f.write('union,' + f'{len(B_uni)},{len(P_uni)}\n')

def list_nudged_subfolders(folder):
    try:
        items = os.listdir(folder)
    except Exception:
        return []
    subs = []
    for it in items:
        p = os.path.join(folder, it)
        if os.path.isdir(p) and it.lower().startswith('nudged'):
            subs.append(p)
    return subs

# ---------- Main ----------
def construct_packing():
    out_root = 'storage/noesis/nmap'
    # Reference folders
    F_N = 'storage/noesis/exports/sota_243'
    F_S = 'storage/Scientia/nmap/n26'
    F_P = 'storage/Prometheus/nmap/n26'
    F_I = 'storage/Inquire/nmap/n26'

    # Read base sets
    Bn, Pn = read_boundary_csv(F_N), read_pairs_csv(F_N)
    Bs, Ps = read_boundary_csv(F_S), read_pairs_csv(F_S)
    Bp, Pp = read_boundary_csv(F_P), read_pairs_csv(F_P)
    Bi, Pi = read_boundary_csv(F_I), read_pairs_csv(F_I)

    # Pairwise Jaccards: Inquire vs refs
    pairs = [('noesis243', (Bn, Pn)), ('scientia259', (Bs, Ps)), ('prometheus298', (Bp, Pp))]
    for tag, (B_ref, P_ref) in pairs:
        sizes = {'boundary': (len(Bi), len(B_ref)), 'pairs': (len(Pi), len(P_ref))}
        bj = jaccard(Bi, B_ref); pj = jaccard(Pi, P_ref)
        out_base = os.path.join(out_root, f'jaccard_inquire_sota_vs_{tag}_tol1e8')
        write_jaccard(out_base, bj, pj, sizes, meta={'A':'Inquire_SOTA','B':tag})

    # 4-lineage consensus on base sets (N,S,P,I)
    sets_dict = {'N': (Bn, Pn), 'S': (Bs, Ps), 'P': (Bp, Pp), 'I': (Bi, Pi)}
    write_consensus(os.path.join(out_root, 'consensus_n26_4lineage_latest_tol1e8'), sets_dict)

    # Map all Inquire/Nudged_* vs refs
    nudged = list_nudged_subfolders(F_I)
    count_n = 0
    for nd in nudged:
        Bi_n, Pi_n = read_boundary_csv(nd), read_pairs_csv(nd)
        name = os.path.basename(nd)
        for tag, (B_ref, P_ref) in pairs:
            sizes = {'boundary': (len(Bi_n), len(B_ref)), 'pairs': (len(Pi_n), len(P_ref))}
            bj = jaccard(Bi_n, B_ref); pj = jaccard(Pi_n, P_ref)
            out_base = os.path.join(out_root, 'inquire_nudged', name, f'jaccard_{name}_vs_{tag}_tol1e8')
            write_jaccard(out_base, bj, pj, sizes, meta={'A':name,'B':tag})
        # Also vs Inquire SOTA itself
        sizes = {'boundary': (len(Bi_n), len(Bi)), 'pairs': (len(Pi_n), len(Pi))}
        bj = jaccard(Bi_n, Bi); pj = jaccard(Pi_n, Pi)
        out_base = os.path.join(out_root, 'inquire_nudged', name, f'jaccard_{name}_vs_inquire_sota_tol1e8')
        write_jaccard(out_base, bj, pj, sizes, meta={'A':name,'B':'Inquire_SOTA'})
        count_n += 1

    print(f'[INGEST] Inquire base sets: |B|={len(Bi)}, |P|={len(Pi)}')
    print(f'[INGEST] Nudged processed: {count_n}')

    centers, radii = load_noesis_pack()
    return centers, radii
